mapper.select:
select blog.* , user.name as userName from collect left join blog on collect.fid = blog.id left join category on blog.category_id = category.id left join user on blog.user_id = user.id
and collect.module = '博客' and blog.title like concat('%',#{title},'%') and category.name like concat('%',#{categoryName},'%') and user.name like concat('%',#{userName},'%') and collect.user_id = #{userId}
order by date desc

select blog.* , user.name as userName from comment left join blog on comment.fid = blog.id left join category on blog.category_id = category.id left join user on blog.user_id = user.id
and comment.module = '博客' and blog.title like concat('%',#{title},'%') and category.name like concat('%',#{categoryName},'%') and user.name like concat('%',#{userName},'%') and comment.user_id = #{userId}
group by comment.fid , comment.module order by date desc
